            new Quote { Id = "https://en.wikiquote.org/wiki/Alan_Turing", Text = "The machine is supplied with a \"tape\" (the analogue of paper) running through it, and divided into sections (called \"squares\") each capable of bearing a \"symbol\".", Author = "Alan Turing" },
