            new Quote { Id = "https://en.wikiquote.org/wiki/Alan_Turing", Text = "I believe that at the end of the century the use of words and general educated opinion will have altered so much that one will be able to speak of machines thinking without expecting to be contradicted.", Author = "Alan Turing" },
