            new Quote { Id = "https://en.wikiquote.org/wiki/Alan_Turing", Text = "Alan Turing was the first to make a careful analysis of the potential capabilities of machines, inventing his famous \"Turing machines\" for the purpose.", Author = "Michael J. Beeson" },
