            new Quote { Id = "https://en.wikiquote.org/wiki/Alan_Turing", Text = "Turing showed that in a certain sense, it is impossible to mechanize mathematics: We shall never be able to build an \"oracle\" machine that can correctly answer all mathematical questions presented to it with a \"yes\" or \"no\" answer.", Author = "Michael J. Beeson" },
